<?php
$file = 'app/Migration/Teams/TeamsImporter.php';
$content = file_get_contents($file);

// The apply method to insert after planMedia (after the return new TeamsMediaPlan line)
// Find the position after the planMedia function ends and before storeMedia
$search = "        return new \\\\App\\\\Migration\\\\Teams\\\\TeamsMediaPlan(\n            featuredPlan: \$featuredPlan,\n            featuredDecided: \$featuredDecided,\n            featuredPath: \$featuredPath,\n            galleryPlans: [],\n            galleryPaths: [],\n            galleryComplete: true,\n            attachments: \$attachments\n        );\n    }\n\n    /** Store planned media files and return stored paths. */";

$replace = "        return new \\\\App\\\\Migration\\\\Teams\\\\TeamsMediaPlan(\n            featuredPlan: \$featuredPlan,\n            featuredDecided: \$featuredDecided,\n            featuredPath: \$featuredPath,\n            galleryPlans: [],\n            galleryPaths: [],\n            galleryComplete: true,\n            attachments: \$attachments\n        );\n    }\n\n    /**\n     * Store planned media files and persist the team member record.\n     *\n     * This handles copying featured images from the media manifest to Laravel storage,\n     * then creating or updating the TeamMember record and its wp_import_map entry.\n     *\n     * @param item The WordPress export item being imported\n     * @param target The existing TeamMember record (null if creating new)\n     * @param category The TeamCategory for this member (can be null if using default)\n     * @param columns The Laravel model attributes\n     * @param media The media plan for featured image\n     * @param mapping The existing wp_import_map entry (null if new)\n * @param sourceHash The source hash for change detection\n     * @param report The import report for tracking\n     * @param execute Whether to actually perform writes\n     */\n    private function apply(\n        WordPressItem $item,\n        ?TeamMember $target,\n        ?TeamCategory $category,\n        array $columns,\n        TeamsMediaPlan $media,\n        ?WpImportMap $mapping,\n        string $sourceHash,\n        TeamsImportReport $report,\n        bool $execute,\n    ): void {\n        $label = $this->label($item);\n        $offset = $this->mediaImporter->createdCount();\n\n        try {\n            if ($execute) {\n                DB::beginTransaction();\n            }\n\n            [$featuredPath, $galleryPaths] = $this->storeMedia($media, $execute);\n\n            if ($execute) {\n                if (array_key_exists('photograph_path', $columns)) {\n                    $columns['photograph_path'] = $featuredPath;\n                }\n\n                $this->doPersist($item, $target, $category, $columns, $media, $mapping, $sourceHash);\n\n                DB::commit();\n            }\n\n            if ($target === null) {\n                $report->created++;\n            } else {\n                $report->updated++;\n            }\n\n            $report->categoryAssignments++;\n            $report->mappingRows++;\n            $this->countAttachmentMappings($media, $report);\n        } catch (Throwable $exception) {\n            if ($execute && DB::transactionLevel() > 0) {\n                DB::rollBack();\n            }\n\n            $copied = $execute ? $this->mediaImporter->createdSince($offset) : [];\n\n            if ($copied !== []) {\n                $report->orphanedFiles = [...$report->orphanedFiles, ...$this->mediaImporter->releaseCreated($copied)];\n            }\n\n            $report->fail($label.': '.$exception->getMessage());\n        }\n    }\n\n    /** Store planned media files and return stored paths. */";

$content = str_replace($search, $replace, $content);

file_put_contents($file, $content);
echo "Apply method added\n";